import * as C from './core.js';
import * as DB from './storage.js';
const button=document.querySelector('#run'),results=document.querySelector('#results'),summary=document.querySelector('#summary');
button.onclick=async()=>{button.disabled=true;results.textContent='';summary.textContent='Vérification en cours…';let count=0;const name='nr-trans-diagnostic-'+C.uid();const ok=(condition,message)=>{if(!condition)throw Error(message);const li=document.createElement('li');li.textContent='✓ '+message;results.append(li);count++;};try{await DB.openDB(name);ok(await DB.read()===null,'Nouvelle base isolée accessible');let s=await DB.save(C.demo(),null);ok(s.days.length>30,'Démonstration enregistrée dans IndexedDB');s.expenses.push({id:C.uid(),date:C.today(),vehicleId:'v1',category:'Autre',description:'Diagnostic',amount:1234,method:'Espèces',comment:'Test'});s.movements.push({id:C.uid(),date:C.today(),type:'Apport propriétaire',ownerId:'o1',amount:7777,comment:'Test'});s=await DB.save(s,s.revision);ok(s.expenses.at(-1).amount===1234,'Opérations supplémentaires enregistrées');const exported=JSON.stringify(C.backup(s)),totals=JSON.stringify(C.stats(s)),original=JSON.stringify(s);DB.closeDB();await DB.openDB(name);ok(JSON.stringify(await DB.read())===original,'Persistance après fermeture et réouverture de la connexion');let refused=false;try{C.parseBackup('{invalide');}catch{refused=true;}ok(refused&&JSON.stringify(await DB.read())===original,'JSON invalide refusé sans perte de données');const old=JSON.parse(exported);old.schemaVersion=0;refused=false;try{C.parseBackup(JSON.stringify(old));}catch{refused=true;}ok(refused,'Ancienne version refusée proprement');const previous=s.revision;s=await DB.save(C.blank(),previous);ok((await DB.read()).days.length===0,'Réinitialisation : anciennes opérations absentes');s=await DB.save(C.parseBackup(exported),s.revision);ok(JSON.stringify(C.stats(s))===totals,'Restauration : tous les totaux sont strictement identiques');ok(s.expenses.at(-1).amount===1234&&s.movements.at(-1).amount===7777,'Restauration : opérations supplémentaires retrouvées');refused=false;try{await DB.save(C.blank(),previous);}catch{refused=true;}ok(refused&&JSON.stringify(C.stats(await DB.read()))===totals,'Protection contre une écriture depuis un onglet obsolète');const invalid=structuredClone(s);invalid.days[0].actual=-1;refused=false;try{await DB.save(invalid,s.revision);}catch{refused=true;}ok(refused&&JSON.stringify(C.stats(await DB.read()))===totals,'Données invalides refusées avant écriture');summary.textContent=count+' vérifications réussies. Pour vérifier le mode hors ligne, revenez à l’application, coupez Internet et rechargez la page.';}catch(e){summary.textContent='Échec : '+e.message;summary.className='negative';}finally{DB.closeDB();indexedDB.deleteDatabase(name);button.disabled=false;}};
